  const invoice = {
    lines: [
      { qty: 50, unitPrice: 200, discountPercent: 15, vatRate: 21 },
      { qty: 30, unitPrice: 300, discountPercent: 5, vatRate: 9 },
    ],
    voucher: { code: 'SAVE', amount: 500 },
  };
  const result = invoiceTotals(invoice);

  const calculated = result.subtotal - result.discount + result.vat - result.voucher;
  assert.equal(result.total, Math.max(0, calculated));
});

test('lineDiscount includes bulk discount for qty >= 10', () => {
  const line = { qty: 10, unitPrice: 1000, vatRate: 21 };
  const discount = lineDiscount(line);

  const lineTotal1 = 10000;
  const bulkDiscount = roundCents((lineTotal1 * 2.5) / 100);
  assert.equal(discount, bulkDiscount);
});

test('lineDiscount applies bulk discount after first discount', () => {
  const line = { qty: 10, unitPrice: 1000, discountPercent: 10, vatRate: 21 };
  const discount = lineDiscount(line);

  const lineTotal1 = 10000;
  const firstDiscount = 1000;
  const amountAfterFirst = lineTotal1 - firstDiscount;
  const bulkDiscount = roundCents((amountAfterFirst * 2.5) / 100);
  const expected = firstDiscount + bulkDiscount;

  assert.equal(discount, expected);
});

test('lineDiscount no bulk discount for qty < 10', () => {
  const line = { qty: 9, unitPrice: 1000, vatRate: 21 };
  const discount = lineDiscount(line);

  assert.equal(discount, 0);
});

test('lineDiscount no bulk discount for qty = 9', () => {
  const line = { qty: 9, unitPrice: 1000, discountPercent: 10, vatRate: 21 };
  const discount = lineDiscount(line);

  const lineTotal1 = 9000;
  const expected = 900;
  assert.equal(discount, expected);
});

test('lineDiscount bulk discount only applied once', () => {
  const line = { qty: 20, unitPrice: 1000, vatRate: 21 };
  const discount = lineDiscount(line);

  const lineTotal1 = 20000;
  const bulkDiscount = roundCents((lineTotal1 * 2.5) / 100);
  assert.equal(discount, bulkDiscount);
});

test('lineDiscount with both line discount and bulk discount', () => {
  const line = { qty: 20, unitPrice: 1000, discountPercent: 5, vatRate: 21 };
  const discount = lineDiscount(line);

  const lineTotal1 = 20000;
  const firstDiscount = 1000;
  const amountAfterFirst = 19000;
  const bulkDiscount = roundCents((amountAfterFirst * 2.5) / 100);
  const expected = firstDiscount + bulkDiscount;

  assert.equal(discount, expected);
});

test('lineVAT calculated on amount after bulk discount', () => {
  const line = { qty: 10, unitPrice: 1000, vatRate: 21 };
  const vat = lineVAT(line);

  const lineTotal1 = 10000;
  const bulkDiscount = roundCents((lineTotal1 * 2.5) / 100);
  const baseForVat = lineTotal1 - bulkDiscount;
  const expected = roundCents((baseForVat * 21) / 100);

  assert.equal(vat, expected);
});

test('invoiceTotals with bulk discount', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, vatRate: 21 },
    ],
  };
  const result = invoiceTotals(invoice);

  const lineTotal1 = 10000;
  const bulkDiscount = roundCents((lineTotal1 * 2.5) / 100);
  const baseForVat = lineTotal1 - bulkDiscount;
  const vat = roundCents((baseForVat * 21) / 100);

  assert.equal(result.subtotal, 10000);
  assert.equal(result.discount, bulkDiscount);
  assert.equal(result.vat, vat);
  assert.equal(result.total, lineTotal1 + vat - bulkDiscount);
});

test('invoiceTotals with multiple lines, some with bulk discount', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, vatRate: 21 },
      { qty: 5, unitPrice: 1000, vatRate: 21 },
    ],
  };
  const result = invoiceTotals(invoice);

  const line1Total = 10000;
  const line2Total = 5000;
  const subtotal = 15000;
  const line1BulkDiscount = roundCents((line1Total * 2.5) / 100);
  const totalDiscount = line1BulkDiscount;
  const baseForVat = subtotal - totalDiscount;
  const vat = roundCents((baseForVat * 21) / 100);

  assert.equal(result.subtotal, subtotal);
  assert.equal(result.discount, totalDiscount);
  assert.equal(result.vat, vat);
});

test('lineDiscount with 0% line discount and bulk discount', () => {
  const line = { qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 21 };
  const discount = lineDiscount(line);

  const lineTotal1 = 10000;
  const bulkDiscount = roundCents((lineTotal1 * 2.5) / 100);
  assert.equal(discount, bulkDiscount);
});

test('lineDiscount with 100% line discount', () => {
  const line = { qty: 10, unitPrice: 1000, discountPercent: 100, vatRate: 21 };
  const discount = lineDiscount(line);

  const lineTotal1 = 10000;
  assert.equal(discount, lineTotal1);
});

test('lineDiscount rounding with bulk discount', () => {
  const line = { qty: 10, unitPrice: 333, vatRate: 21 };
  const discount = lineDiscount(line);

  assert.ok(Number.isInteger(discount));
});

test('invoiceTotals with bulk discount and voucher', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, vatRate: 21 },
    ],
    voucher: { code: 'TEST', amount: 500 },
  };
  const result = invoiceTotals(invoice);

  const lineTotal1 = 10000;
  const bulkDiscount = roundCents((lineTotal1 * 2.5) / 100);
  const baseForVat = lineTotal1 - bulkDiscount;
  const vat = roundCents((baseForVat * 21) / 100);
  const total = lineTotal1 + vat - bulkDiscount - 500;

  assert.equal(result.voucher, 500);
  assert.equal(result.total, total);
});

test('lineDiscount bulk discount on large quantity', () => {
  const line = { qty: 100, unitPrice: 500, vatRate: 21 };
  const discount = lineDiscount(line);

  const lineTotal1 = 50000;
  const bulkDiscount = roundCents((lineTotal1 * 2.5) / 100);
  assert.equal(discount, bulkDiscount);
});

test('invoiceTotals with mixed quantities and discounts', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, discountPercent: 10, vatRate: 21 },
      { qty: 15, unitPrice: 500, discountPercent: 5, vatRate: 9 },
      { qty: 3, unitPrice: 2000, discountPercent: 0, vatRate: 21 },
    ],
  };
  const result = invoiceTotals(invoice);

  assert.ok(result.subtotal > 0);
  assert.ok(result.discount > 0);
  assert.ok(result.vat > 0);
  assert.ok(result.total > 0);
});

