1	import { ok, fail } from './result.js';
2	import { roundCents } from './money.js';
3	import { getCustomer, TIER_DISCOUNTS, normalizeId } from './customers.js';
4	import { getProduct } from './catalogue.js';
5	import { nextInvoiceNumber } from './numbering.js';
6	import { isValidDate as validateDate, addDays } from './dates.js';
7	import { lineTotal, lineDiscount, lineVAT, invoiceTotals } from './totals.js';
8	
9	export { lineTotal, lineDiscount, lineVAT, invoiceTotals } from './totals.js';
10	
11	/**
12	 * Create an invoice draft.
13	 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number }>, terms?: string }} input
14	 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
15	 */
16	export function createInvoice({ customerId, issueDate, lines, terms }) {
17	  const normalizedCustomerId = normalizeId(customerId);
18	  const customerResult = getCustomer(normalizedCustomerId);
19	  if (!customerResult.ok) return customerResult;
20	
21	  if (!validateDate(issueDate)) return fail('DATE_INVALID');
22	
23	  if (!lines || lines.length === 0) return fail('NO_LINES');
24	
25	  const finalTerms = terms ?? 'NET30';
26	  const dueDate = calculateDueDate(issueDate, finalTerms);
27	  if (dueDate === null) return fail('TERMS_INVALID');
28	
29	  const customer = customerResult.value;
30	  const tierDiscount = TIER_DISCOUNTS[customer.tier] ?? 0;
31	
32	  const enrichedLines = [];
33	  for (const line of lines) {
34	    if (!Number.isInteger(line.qty) || line.qty <= 0) return fail('QTY_INVALID');
35	
36	    const discountPercent = line.discountPercent !== undefined ? line.discountPercent : tierDiscount;
37	    const discountValidation = validateDiscountPercent(discountPercent);
38	    if (!discountValidation.ok) return discountValidation;
39	
40	    const productResult = getProduct(line.sku);
41	    if (!productResult.ok) return productResult;
42	
43	    const product = productResult.value;
44	    enrichedLines.push({
45	      sku: line.sku,
46	      name: product.name,
47	      qty: line.qty,
48	      unitPrice: product.unitPrice,
49	      vatRate: product.vatRate,
50	      discountPercent: discountValidation.value,
51	    });
52	  }
53	
54	  return ok({
55	    customerId: normalizedCustomerId,
56	    issueDate,
57	    terms: finalTerms,
58	    dueDate,
59	    status: 'draft',
60	    lines: enrichedLines,
61	  });
62	}
