65	/**
66	 * Add or update a line on an invoice.
67	 * @param {any} invoice
68	 * @param {{ sku: string, qty: number, discountPercent?: number }} input
69	 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
70	 */
71	export function addLine(invoice, { sku, qty, discountPercent }) {
72	  if (invoice.status !== 'draft') return fail('NOT_DRAFT');
73	
74	  if (!Number.isInteger(qty) || qty <= 0) return fail('QTY_INVALID');
75	
76	  const discountValidation = validateDiscountPercent(discountPercent);
77	  if (!discountValidation.ok) return discountValidation;
78	
79	  const productResult = getProduct(sku);
80	  if (!productResult.ok) return productResult;
81	
82	  const product = productResult.value;
83	  const newLines = invoice.lines.map((line) => ({ ...line }));
84	  const existingLineIndex = newLines.findIndex((line) => line.sku === sku);
85	
86	  if (existingLineIndex >= 0) {
87	    newLines[existingLineIndex] = {
88	      ...newLines[existingLineIndex],
89	      qty: newLines[existingLineIndex].qty + qty,
90	    };
91	  } else {
92	    newLines.push({
93	      sku,
94	      name: product.name,
95	      qty,
96	      unitPrice: product.unitPrice,
97	      vatRate: product.vatRate,
98	      discountPercent: discountValidation.value,
99	    });
100	  }
101	
102	  return ok({
103	    ...invoice,
104	    lines: newLines,
105	  });
106	}
107	
108	/**
109	 * Remove a line from an invoice.
110	 * @param {any} invoice
111	 * @param {string} sku
112	 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
113	 */
114	export function removeLine(invoice, sku) {
115	  if (invoice.status !== 'draft') return fail('NOT_DRAFT');
116	
117	  const lineIndex = invoice.lines.findIndex((line) => line.sku === sku);
118	  if (lineIndex < 0) return fail('LINE_NOT_FOUND');
119	
120	  if (invoice.lines.length === 1) return fail('NO_LINES');
121	
122	  const newLines = invoice.lines.filter((_, i) => i !== lineIndex).map((line) => ({ ...line }));
123	
124	  return ok({
125	    ...invoice,
126	    lines: newLines,
127	  });
128	}
129	
130	/**
131	 * Apply a voucher to an invoice.
132	 * @param {any} invoice
133	 * @param {{ code: string, amount: number }} voucher
134	 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
135	 */
136	export function applyVoucher(invoice, { code, amount }) {
137	  if (invoice.status !== 'draft') return fail('NOT_DRAFT');
138	
139	  if (invoice.voucher) return fail('VOUCHER_EXISTS');
140	
141	  if (!Number.isInteger(amount) || amount <= 0) return fail('AMOUNT_INVALID');
142	
143	  return ok({
144	    ...invoice,
145	    voucher: { code, amount },
146	  });
147	}
148	
149	/**
150	 * Issue an invoice, assigning it a number and marking it as issued.
151	 * @param {any} invoice
152	 * @param {string[]} existingNumbers - Array of invoice numbers already used
153	 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
154	 */
155	export function issueInvoice(invoice, existingNumbers) {
156	  if (invoice.status !== 'draft') return fail('NOT_DRAFT');
157	
158	  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);
159	
160	  return ok({
161	    ...invoice,
162	    number,
163	    status: 'issued',
164	  });
165	}
166	
167	/**
168	 * Validate and normalize a discount percent value.
169	 * @param {any} value
170	 * @returns {{ ok: true, value: number } | { ok: false, error: string }}
171	 */
172	function validateDiscountPercent(value) {
173	  if (value === undefined || value === null) return ok(0);
174	  if (typeof value !== 'number' || isNaN(value) || value < 0 || value > 100) {
175	    return fail('DISCOUNT_INVALID');
176	  }
177	  return ok(value);
178	}
179	
180	/**
181	 * Calculate the due date based on payment terms.
182	 * @param {string} issueDate - Date in YYYY-MM-DD format
183	 * @param {string} terms - 'NET14', 'NET30', or 'EOM'
184	 * @returns {string|null} - Due date in YYYY-MM-DD format, or null if terms invalid
185	 */
186	function calculateDueDate(issueDate, terms) {
187	  switch (terms) {
188	    case 'NET14':
189	      return addDays(issueDate, 14);
190	    case 'NET30':
191	      return addDays(issueDate, 30);
192	    case 'EOM':
193	      return getLastDayOfMonth(issueDate);
194	    default:
195	      return null;
196	  }
197	}
198	
199	/**
200	 * Get the last day of the month for a given date.
201	 * @param {string} dateStr - Date in YYYY-MM-DD format
202	 * @returns {string} - Last day of month in YYYY-MM-DD format
203	 */
204	function getLastDayOfMonth(dateStr) {
205	  const [year, month] = dateStr.split('-').map(Number);
206	  const lastDay = new Date(year, month, 0);
207	  return `${year}-${String(month).padStart(2, '0')}-${String(lastDay.getDate()).padStart(2, '0')}`;
208	}
