1	import { roundCents } from './money.js';
2	
3	/**
4	 * Calculate the total for a single invoice line (qty * unitPrice).
5	 * @param {{ qty: number, unitPrice: number }} line
6	 * @returns {number}
7	 */
8	export function lineTotal(line) {
9	  return roundCents(line.qty * line.unitPrice);
10	}
11	
12	/**
13	 * Calculate the discount for a single invoice line (including bulk discount for qty >= 10).
14	 * @param {{ discountPercent?: number, qty: number, unitPrice: number }} line
15	 * @returns {number}
16	 */
17	export function lineDiscount(line) {
18	  const percent = line.discountPercent ?? 0;
19	  const total = lineTotal(line);
20	  const firstDiscount = roundCents((total * percent) / 100);
21	
22	  let bulkDiscount = 0;
23	  if (line.qty >= 10) {
24	    const amountAfterFirstDiscount = Math.max(0, total - firstDiscount);
25	    bulkDiscount = roundCents((amountAfterFirstDiscount * 2.5) / 100);
26	  }
27	
28	  const totalDiscount = roundCents(firstDiscount + bulkDiscount);
29	  return Math.max(0, totalDiscount);
30	}
31	
32	/**
33	 * Calculate the VAT for a single invoice line (based on amount after discount).
34	 * @param {{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }} line
35	 * @returns {number}
36	 */
37	export function lineVAT(line) {
38	  const total = lineTotal(line);
39	  const discount = lineDiscount(line);
40	  const amountAfterDiscount = Math.max(0, total - discount);
41	  const vat = roundCents((amountAfterDiscount * line.vatRate) / 100);
42	  return Math.max(0, vat);
43	}
44	
45	/**
46	 * Calculate subtotal, discount, VAT, voucher, and total for an invoice.
47	 * @param {{ lines: Array<{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }>, voucher?: { code: string, amount: number } }} invoice
48	 * @returns {{ subtotal: number, discount: number, vat: number, voucher: number, total: number }}
49	 */
50	export function invoiceTotals(invoice) {
51	  const subtotal = roundCents(invoice.lines.reduce((sum, line) => sum + lineTotal(line), 0));
52	  const discount = roundCents(invoice.lines.reduce((sum, line) => sum + lineDiscount(line), 0));
53	  const vat = roundCents(invoice.lines.reduce((sum, line) => sum + lineVAT(line), 0));
54	  const voucher = invoice.voucher?.amount ?? 0;
55	  const total = Math.max(0, roundCents(subtotal - discount + vat - voucher));
56	
57	  return {
58	    subtotal,
59	    discount,
60	    vat,
61	    voucher,
62	    total,
63	  };
64	}
