import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, lineDiscount, lineVAT, invoiceTotals, addLine, removeLine, issueInvoice, applyVoucher } from '../src/invoices.js';

test('createInvoice creates a draft invoice with enriched lines', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-001');
  assert.equal(result.value.issueDate, '2024-02-15');
  assert.equal(result.value.status, 'draft');
  assert.equal(result.value.lines.length, 2);

  const line1 = result.value.lines[0];
  assert.equal(line1.sku, 'DEV-HOUR');
  assert.equal(line1.name, 'Development (hour)');
  assert.equal(line1.qty, 10);
  assert.equal(line1.unitPrice, 9500);
  assert.equal(line1.vatRate, 21);

  const line2 = result.value.lines[1];
  assert.equal(line2.sku, 'LOGO-PACK');
  assert.equal(line2.name, 'Logo package');
  assert.equal(line2.qty, 1);
  assert.equal(line2.unitPrice, 120000);
  assert.equal(line2.vatRate, 21);
});

test('createInvoice reports CUSTOMER_NOT_FOUND for unknown customer', () => {
  const result = createInvoice({
    customerId: 'C-999',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.deepEqual(result, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('createInvoice reports DATE_INVALID for bad format', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2024/02/15',
      lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );

  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '15-02-2024',
      lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );

  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '02-15',
      lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );
});

test('createInvoice reports DATE_INVALID for non-existent dates', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2024-02-30',
      lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );

  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2023-04-31',
      lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );
});

test('createInvoice accepts valid dates including leap days', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-29',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(result.ok, true);
});

test('createInvoice reports NO_LINES for empty lines array', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2024-02-15',
      lines: [],
    }),
    { ok: false, error: 'NO_LINES' }
  );
});

test('createInvoice reports NO_LINES when lines is missing', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2024-02-15',
      lines: undefined,
    }),
    { ok: false, error: 'NO_LINES' }
  );
});

test('createInvoice reports QTY_INVALID for non-positive quantities', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2024-02-15',
      lines: [{ sku: 'DEV-HOUR', qty: 0 }],
    }),
    { ok: false, error: 'QTY_INVALID' }
  );

  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2024-02-15',
      lines: [{ sku: 'DEV-HOUR', qty: -5 }],
    }),
    { ok: false, error: 'QTY_INVALID' }
  );
});

test('createInvoice reports QTY_INVALID for non-integer quantities', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2024-02-15',
      lines: [{ sku: 'DEV-HOUR', qty: 1.5 }],
    }),
    { ok: false, error: 'QTY_INVALID' }
  );

  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2024-02-15',
      lines: [{ sku: 'DEV-HOUR', qty: '10' }],
    }),
    { ok: false, error: 'QTY_INVALID' }
  );
});

test('createInvoice reports UNKNOWN_SKU for product not in catalogue', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2024-02-15',
      lines: [{ sku: 'UNKNOWN-SKU', qty: 1 }],
    }),
    { ok: false, error: 'UNKNOWN_SKU' }
  );
});

test('createInvoice does not mutate the input array', () => {
  const lines = [
    { sku: 'DEV-HOUR', qty: 10 },
    { sku: 'LOGO-PACK', qty: 1 },
  ];
  const originalJSON = JSON.stringify(lines);

  createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines,
  });

  assert.equal(JSON.stringify(lines), originalJSON);
});

test('lineTotal calculates qty * unitPrice', () => {
  assert.equal(lineTotal({ qty: 10, unitPrice: 9500 }), 95000);
  assert.equal(lineTotal({ qty: 1, unitPrice: 120000 }), 120000);
  assert.equal(lineTotal({ qty: 100, unitPrice: 50 }), 5000);
});

test('lineTotal returns whole cents', () => {
  const line = { qty: 3, unitPrice: 333 };
  const total = lineTotal(line);
  assert.equal(total, 999);
  assert.equal(total % 1, 0);
});

test('invoiceTotals returns correct subtotal, discount, vat, voucher, and total', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-02-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  }).value;

  const totals = invoiceTotals(invoice);
  const subtotal = 95000 + 120000;
  const devBulkDiscount = 2375;
  const logoDiscount = 0;
  const devVATBase = 95000 - devBulkDiscount;
  const devVAT = roundCents((devVATBase * 21) / 100);
  const logoVAT = roundCents((120000 * 21) / 100);

  assert.deepEqual(totals, {
    subtotal,
    discount: devBulkDiscount + logoDiscount,
    vat: devVAT + logoVAT,
    voucher: 0,
    total: subtotal - (devBulkDiscount + logoDiscount) + devVAT + logoVAT,
  });
});

test('invoiceTotals with single line', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-02-15',
    lines: [{ sku: 'SUPPORT-HOUR', qty: 5 }],
  }).value;

  const totals = invoiceTotals(invoice);
  const subtotal = 5 * 7250;

  assert.equal(totals.subtotal, subtotal);
  assert.equal(totals.total, subtotal + totals.vat);
});

test('invoiceTotals with many lines', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-02-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'COPY-HOUR', qty: 5 },
      { sku: 'SUPPORT-HOUR', qty: 3 },
      { sku: 'ICON-SET', qty: 20 },
    ],
  }).value;

  const expected = 10 * 9500 + 5 * 6000 + 3 * 7250 + 20 * 980;
  const vat = Math.round((expected * 21) / 100);
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, expected);
  assert.equal(totals.vat, vat);
  assert.equal(totals.total, expected + vat);
});

test('invoiceTotals returns whole cents', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [
      { sku: 'PHOTO-LIC', qty: 3 },
      { sku: 'FONT-LIC', qty: 2 },
    ],
  }).value;

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal % 1, 0);
  assert.equal(totals.total % 1, 0);
});

test('addLine adds a new line to an invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  const result = addLine(invoice, { sku: 'LOGO-PACK', qty: 1 });
  assert.equal(result.ok, true);

  const newInvoice = result.value;
  assert.equal(newInvoice.lines.length, 2);
  assert.equal(newInvoice.lines[1].sku, 'LOGO-PACK');
  assert.equal(newInvoice.lines[1].qty, 1);
});

test('addLine increases qty if SKU already exists', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  const result = addLine(invoice, { sku: 'DEV-HOUR', qty: 3 });
  assert.equal(result.ok, true);

  const newInvoice = result.value;
  assert.equal(newInvoice.lines.length, 1);
  assert.equal(newInvoice.lines[0].sku, 'DEV-HOUR');
  assert.equal(newInvoice.lines[0].qty, 8);
});

test('addLine does not mutate the original invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  const originalJSON = JSON.stringify(invoice);
  addLine(invoice, { sku: 'LOGO-PACK', qty: 1 });
  assert.equal(JSON.stringify(invoice), originalJSON);
});

test('addLine reports QTY_INVALID for bad quantities', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  assert.deepEqual(addLine(invoice, { sku: 'LOGO-PACK', qty: 0 }), {
    ok: false,
    error: 'QTY_INVALID',
  });

  assert.deepEqual(addLine(invoice, { sku: 'LOGO-PACK', qty: -5 }), {
    ok: false,
    error: 'QTY_INVALID',
  });

  assert.deepEqual(addLine(invoice, { sku: 'LOGO-PACK', qty: 1.5 }), {
    ok: false,
    error: 'QTY_INVALID',
  });
});

test('addLine reports UNKNOWN_SKU for invalid SKU', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  assert.deepEqual(addLine(invoice, { sku: 'INVALID-SKU', qty: 1 }), {
    ok: false,
    error: 'UNKNOWN_SKU',
  });
});

test('addLine reports NOT_DRAFT for non-draft invoices', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  const nonDraftInvoice = { ...invoice, status: 'sent' };

  assert.deepEqual(addLine(nonDraftInvoice, { sku: 'LOGO-PACK', qty: 1 }), {
    ok: false,
    error: 'NOT_DRAFT',
  });
});

test('removeLine removes a line from an invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'LOGO-PACK', qty: 1 },
      { sku: 'SUPPORT-HOUR', qty: 3 },
    ],
  }).value;

  const result = removeLine(invoice, 'LOGO-PACK');
  assert.equal(result.ok, true);

  const newInvoice = result.value;
  assert.equal(newInvoice.lines.length, 2);
  assert.equal(newInvoice.lines[0].sku, 'DEV-HOUR');
  assert.equal(newInvoice.lines[1].sku, 'SUPPORT-HOUR');
});

test('removeLine does not mutate the original invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  }).value;

  const originalJSON = JSON.stringify(invoice);
  removeLine(invoice, 'LOGO-PACK');
  assert.equal(JSON.stringify(invoice), originalJSON);
});

test('removeLine reports LINE_NOT_FOUND for unknown SKU', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  assert.deepEqual(removeLine(invoice, 'UNKNOWN-SKU'), {
    ok: false,
    error: 'LINE_NOT_FOUND',
  });
});

test('removeLine reports NO_LINES when removing the last line', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  assert.deepEqual(removeLine(invoice, 'DEV-HOUR'), {
    ok: false,
    error: 'NO_LINES',
  });
});

test('removeLine reports NOT_DRAFT for non-draft invoices', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  }).value;

  const nonDraftInvoice = { ...invoice, status: 'sent' };

  assert.deepEqual(removeLine(nonDraftInvoice, 'LOGO-PACK'), {
    ok: false,
    error: 'NOT_DRAFT',
  });
});

test('issueInvoice assigns a number and changes status to issued', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  const result = issueInvoice(invoice, []);
  assert.equal(result.ok, true);

  const issued = result.value;
  assert.equal(issued.number, 'INV-2024-0001');
  assert.equal(issued.status, 'issued');
  assert.equal(issued.customerId, invoice.customerId);
  assert.equal(issued.issueDate, invoice.issueDate);
});

test('issueInvoice assigns next number when some already exist', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  const existing = ['INV-2024-0001', 'INV-2024-0002'];
  const result = issueInvoice(invoice, existing);
  assert.equal(result.ok, true);
  assert.equal(result.value.number, 'INV-2024-0003');
});

test('issueInvoice assigns number by year of issue date', () => {
  const invoice2023 = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-06-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  const invoice2024 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  const existing = ['INV-2023-0005', 'INV-2024-0001'];

  const result2023 = issueInvoice(invoice2023, existing);
  assert.equal(result2023.value.number, 'INV-2023-0006');

  const result2024 = issueInvoice(invoice2024, existing);
  assert.equal(result2024.value.number, 'INV-2024-0002');
});

test('issueInvoice does not mutate the original invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  const originalJSON = JSON.stringify(invoice);
  issueInvoice(invoice, []);
  assert.equal(JSON.stringify(invoice), originalJSON);
});

test('issueInvoice reports NOT_DRAFT for non-draft invoices', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  const issuedInvoice = { ...invoice, status: 'issued' };

  assert.deepEqual(issueInvoice(issuedInvoice, []), {
    ok: false,
    error: 'NOT_DRAFT',
  });
});

test('createInvoice applies tier discount when no explicit discount given', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 0);
});

test('createInvoice accepts valid discount percentages', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 10, discountPercent: 0 },
      { sku: 'LOGO-PACK', qty: 1, discountPercent: 50 },
      { sku: 'SUPPORT-HOUR', qty: 5, discountPercent: 12.5 },
      { sku: 'ICON-SET', qty: 20, discountPercent: 100 },
    ],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 0);
  assert.equal(result.value.lines[1].discountPercent, 50);
  assert.equal(result.value.lines[2].discountPercent, 12.5);
  assert.equal(result.value.lines[3].discountPercent, 100);
});

test('createInvoice reports DISCOUNT_INVALID for invalid discounts', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2024-02-15',
      lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 101 }],
    }),
    { ok: false, error: 'DISCOUNT_INVALID' }
  );

  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2024-02-15',
      lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: -1 }],
    }),
    { ok: false, error: 'DISCOUNT_INVALID' }
  );

  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2024-02-15',
      lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 'fifty' }],
    }),
    { ok: false, error: 'DISCOUNT_INVALID' }
  );

  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2024-02-15',
      lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: NaN }],
    }),
    { ok: false, error: 'DISCOUNT_INVALID' }
  );
});

test('lineDiscount calculates correct discount amount', () => {
  assert.equal(lineDiscount({ qty: 10, unitPrice: 1000, discountPercent: 10 }), 1000);
  assert.equal(lineDiscount({ qty: 100, unitPrice: 100, discountPercent: 50 }), 5000);
  assert.equal(lineDiscount({ qty: 3, unitPrice: 333, discountPercent: 0 }), 0);
  assert.equal(lineDiscount({ qty: 1, unitPrice: 1000, discountPercent: 100 }), 1000);
});

test('lineDiscount defaults to 0 when discountPercent is undefined', () => {
  assert.equal(lineDiscount({ qty: 10, unitPrice: 1000 }), 0);
});

test('lineDiscount clamps to 0 (never negative)', () => {
  const line = { qty: 10, unitPrice: 1000, discountPercent: 50 };
  const discount = lineDiscount(line);
  assert.ok(discount >= 0);
});

test('invoiceTotals includes subtotal, discount, vat, and total', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 10, discountPercent: 10 },
      { sku: 'LOGO-PACK', qty: 1, discountPercent: 0 },
    ],
  }).value;

  const totals = invoiceTotals(invoice);

  const devTotal = 95000;
  const devDiscount = Math.round((devTotal * 10) / 100);
  const devAfterDiscount = devTotal - devDiscount;
  const devVAT = Math.round((devAfterDiscount * 21) / 100);
  const logoVAT = Math.round((120000 * 21) / 100);

  assert.equal(totals.subtotal, 95000 + 120000);
  assert.equal(totals.discount, devDiscount);
  assert.equal(totals.vat, devVAT + logoVAT);
  assert.equal(totals.total, 95000 - devDiscount + 120000 + devVAT + logoVAT);
});

test('invoiceTotals calculates zero discount when no discounts applied', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-02-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  }).value;

  const totals = invoiceTotals(invoice);

  assert.equal(totals.discount, 0);
  assert.equal(totals.total, totals.subtotal + totals.vat);
});

test('invoiceTotals clamps total to 0 if discount exceeds subtotal', () => {
  const invoice = {
    lines: [{ qty: 1, unitPrice: 1000, discountPercent: 150, vatRate: 0 }],
  };

  const totals = invoiceTotals(invoice);

  assert.ok(totals.total >= 0);
});

test('addLine accepts discount percentage', () => {
  const invoice = createInvoice({
